const e="atlante-visuale",t="atlante-visuale",a="https://precious-cassata-42205a.netlify.app/atlante-visuale",o="Atlante Visuale &mdash; Metodo Pentaedrico &mdash; MetaHistoria",s="",c="",i="atlante-visuale",u=null,l=[{type:"p",role:"p",runs:[{t:"Metodo Pentaedrico — L’Identità Visiva"}]},{type:"h",level:1,runs:[{t:"Atlante Visuale"}],role:"p"},{type:"p",role:"lede",runs:[{t:"Trenta tavole per mappare l’architettura di MetaHistoria: dalla genealogia del potere alla cartografia dell’anima, dal Metodo Pentaedrico all’Apocalisse della storia."}]},{type:"p",role:"p",runs:[{t:"30",b:!0},{t:" Tavole nel programma "},{t:"6",b:!0},{t:" Pubblicate In costruzione"}]},{type:"h",level:3,runs:[{t:"Non semplici illustrazioni: l’identità visiva del Metodo"}],role:"p"},{type:"p",role:"p",runs:[{t:"Le tavole dell’Atlante non sono decorazioni. Sono "},{t:"mappe ontologiche",b:!0},{t:": schemi ufficiali del Metodo Pentaedrico utilizzabili nel sito, nei libri, nelle lezioni e nelle conferenze. Ogni tavola è numerata, titolata e accompagnata da una didascalia che ne spiega la posizione nell’architettura complessiva. L’Atlante crescerà una tavola alla volta, fino a coprire l’intero sistema."}]},{type:"p",role:"p",runs:[{t:"Non una semplice mappa mentale, ma una mappa ontologica del sito: una rappresentazione dell’architettura di MetaHistoria. Dovrebbe essere il DNA del progetto."}]},{type:"quote",runs:[{t:"Non una semplice mappa mentale, ma una mappa ontologica del sito: una rappresentazione dell’architettura di MetaHistoria. Dovrebbe essere il DNA del progetto.Documento di progetto — Schemi MetaHistoria"}]},{type:"p",role:"p",runs:[{t:"01"}]},{type:"h",level:2,runs:[{t:"L’Architettura di MetaHistoria"}],role:"p"},{type:"p",role:"p",runs:[{t:"Mappa ontologica"}]},{type:"p",role:"p",runs:[{t:"La tavola fondativa: l’albero genealogico dell’intero sistema. Da Dio — Rivelazione e Verità — discende la Storia della Salvezza, applicata alla storia umana attraverso il "},{t:"Metodo Pentaedrico",b:!0},{t:". Le cinque lenti si diramano come rami di uno stesso tronco, ciascuna col proprio oggetto (Stati, Popoli, Civiltà, Discernimento, Destino) e le proprie categorie operative (Confini, Memoria, Cuore, Idolatria, Giudizio e così via)."}]},{type:"p",role:"p",runs:[{t:"Tavola 01 — L’Architettura di MetaHistoria. La mappa ontologica del sistema."}]},{type:"p",role:"p",runs:[{t:"02"}]},{type:"h",level:2,runs:[{t:"Il Metodo Pentaedrico"}],role:"p"},{type:"p",role:"p",runs:[{t:"Come funziona"}]},{type:"p",role:"p",runs:[{t:"Come funziona il Metodo: la discesa dall’"},{t:"Evento Storico",b:!0},{t:" attraverso le cinque domande progressive. Ogni lente risponde a una domanda diversa e usa fonti proprie: Cosa è successo? (Geopolitica Classica) → A chi è successo? (Geopolitica Umana) → Perché quel popolo agisce così? (Geopolitica dell’Anima) → Come giudica questo potere la Rivelazione? (Teologia della Geopolitica) → Qual è il destino di questo potere? (Apocalisse del Potere)."}]},{type:"p",role:"p",runs:[{t:"Tavola 02 — Il funzionamento del Metodo Pentaedrico: le cinque domande progressive."}]},{type:"p",role:"p",runs:[{t:"03"}]},{type:"h",level:2,runs:[{t:"Le Cinque Lenti"}],role:"p"},{type:"p",role:"p",runs:[{t:"Strumenti"}]},{type:"p",role:"p",runs:[{t:"Ogni lente col suo "},{t:"oggetto",b:!0},{t:", la sua "},{t:"domanda guida",b:!0},{t:", le sue "},{t:"fonti",b:!0},{t:" e il suo "},{t:"criterio di verità",b:!0},{t:". Dalla superficie osservabile (territorio, confini, potenza) fino alla profondità del destino ultimo (Regno, Escaton, Giudizio). Le cinque lenti non si contraddicono: si completano."}]},{type:"p",role:"p",runs:[{t:"Tavola 03 — Le Cinque Lenti: oggetto, domanda guida e fonti di ciascuna."}]},{type:"p",role:"p",runs:[{t:"04"}]},{type:"h",level:2,runs:[{t:"Il Percorso dell’Interpretazione Storica"}],role:"p"},{type:"p",role:"p",runs:[{t:"Progressione epistemologica"}]},{type:"p",role:"p",runs:[{t:"La progressione epistemologica: come ogni lente "},{t:"espande la precedente senza annullarla",b:!0},{t:". Dalla superficie osservabile al giudizio dell’Escaton, il lettore viene accompagnato da ciò che è visibile fino a ciò che richiede discernimento. Non cinque analisi indipendenti, ma un cammino progressivo attraverso i livelli della realtà."}]},{type:"p",role:"p",runs:[{t:"Tavola 04 — Il percorso dell’interpretazione storica attraverso le cinque lenti."}]},{type:"p",role:"p",runs:[{t:"05"}]},{type:"h",level:2,runs:[{t:"La Genealogia del Potere"}],role:"p"},{type:"p",role:"p",runs:[{t:"Catena causale"}]},{type:"p",role:"p",runs:[{t:"La catena che lega l’interiorità alla storia mondiale: il "},{t:"cuore",b:!0},{t:" genera civiltà; le "},{t:"civiltà",b:!0},{t:" producono imperi; gli "},{t:"imperi",b:!0},{t:" costruiscono la storia; "},{t:"Dio",b:!0},{t:" giudica la storia; la "},{t:"storia",b:!0},{t:" tende al Regno. Ogni evento storico è un’epifania del potere, e ogni potere ha una genealogia spirituale che risale al cuore dell’uomo e alla sua immagine di Dio."}]},{type:"p",role:"p",runs:[{t:"Tavola 05 — La genealogia del potere: cuore → civiltà → impero → giudizio → Regno."}]},{type:"p",role:"p",runs:[{t:"06"}]},{type:"h",level:2,runs:[{t:"La Cartografia dell’Anima Collettiva"}],role:"p"},{type:"p",role:"p",runs:[{t:"Struttura frattale"}]},{type:"p",role:"p",runs:[{t:"La "},{t:"struttura frattale",b:!0},{t:" dell’anima: ciò che accade nell’anima individuale si riflette nell’anima collettiva di una civiltà e nella sua proiezione geopolitica. La ferita originaria, il desiderio di salvezza, la paura dell’annientamento non sono solo sentimenti: sono "},{t:"forze geopolitiche",b:!0},{t:". Mapparle significa capire perché i popoli combattono."}]},{type:"p",role:"p",runs:[{t:"Tavola 06 — La cartografia dell’anima collettiva e la sua proiezione geopolitica."}]},{type:"p",role:"p",runs:[{t:"07"}]},{type:"h",level:2,runs:[{t:"La Dinamica Cuore → Civiltà → Impero"}],role:"p"},{type:"p",role:"p",runs:[{t:"Prossimamente"}]},{type:"p",role:"p",runs:[{t:"Il movimento dall’interiorità alla storia: come una ferita originaria diventa motore imperiale, e come un desiderio di salvezza si corrompe in volontà di potenza."}]},{type:"p",role:"p",runs:[{t:"08"}]},{type:"h",level:2,runs:[{t:"La Teologia della Storia"}],role:"p"},{type:"p",role:"p",runs:[{t:"Prossimamente"}]},{type:"p",role:"p",runs:[{t:"La Storia della Salvezza come chiave di lettura della storia umana: Creazione, Caduta, Incarnazione, Croce, Resurrezione, Pentecoste, Escaton."}]},{type:"p",role:"p",runs:[{t:"09"}]},{type:"h",level:2,runs:[{t:"L’Apocalisse del Potere"}],role:"p"},{type:"p",role:"p",runs:[{t:"Prossimamente"}]},{type:"p",role:"p",runs:[{t:"Le quattro figure (Anticristo, Impero, Katechon, Cristo) a confronto tra Peter Thiel e la TGR. La griglia dei Dieci Sistemi di Dominio."}]},{type:"p",role:"p",runs:[{t:"10"}]},{type:"h",level:2,runs:[{t:"Applicazione del Metodo alla Guerra in Ucraina"}],role:"p"},{type:"p",role:"p",runs:[{t:"Prossimamente"}]},{type:"p",role:"p",runs:[{t:"Il caso guida visualizzato: l’albero decisionale delle cinque lenti applicato al conflitto ucraino, dalle cause geostrategiche al giudizio escatologico."}]},{type:"p",role:"p",runs:[{t:"Altre venti tavole sono in programma per completare l’Atlante, coprendo le cinque profondità della realtà, il pentagono ermeneutico, la scala delle cinque domande e molto altro. Ogni nuova tavola sarà pubblicata in questa pagina non appena disponibile."}]},{type:"p",role:"p",runs:[{t:"← Il Metodo Pentaedrico Biblioteca Pentaedrica →"}]}],r=[],n=[],p={blocks:56,chars:5084,hash:"a5323e1538a2af06ce0d2c80ee8775d29f22865cf4caf28f4187c0b228e36731"},d={id:e,slug:t,sourceUrl:a,title:o,kicker:"",lede:"",category:i,parentId:null,blocks:l,prevNext:r,references:n,stats:p};export{l as blocks,i as category,d as default,e as id,s as kicker,c as lede,u as parentId,r as prevNext,n as references,t as slug,a as sourceUrl,p as stats,o as title};
